diff --git a/apps/webapp/src/app/[locale]/(app)/organization/org-explorer-client.test.tsx b/apps/webapp/src/app/[locale]/(app)/organization/org-explorer-client.test.tsx
index 5e9e61135..5713775eb 100644
--- a/apps/webapp/src/app/[locale]/(app)/organization/org-explorer-client.test.tsx
+++ b/apps/webapp/src/app/[locale]/(app)/organization/org-explorer-client.test.tsx
@@ -739,6 +739,19 @@ describe("OrgExplorerClient", () => {
 			noTeamCount: 120,
 		};

+		it("recovers a failed deep-linked person without losing the selected URL or showing a different person", async () => {
+			mocks.people.mockResolvedValueOnce({ success: false, error: "Unavailable" });
+			await renderExplorer({ initialData: partial, search: "?employee=deb" });
+			const panel = await screen.findByRole("dialog");
+			expect(await within(panel).findByRole("alert")).toBeTruthy();
+			expect(within(panel).queryByRole("heading", { name: "Ada Analyst" })).toBeNull();
+			expect(query().get("employee")).toBe("deb");
+			mocks.people.mockResolvedValue({ success: true, data: [people[4]] });
+			fireEvent.click(within(panel).getByRole("button", { name: "Retry" }));
+			expect(await within(panel).findByRole("heading", { name: "Deb Dev" })).toBeTruthy();
+			expect(query().get("employee")).toBe("deb");
+		});
+
 		it("loads a subtree on demand when it is expanded", async () => {
 			mocks.people.mockResolvedValueOnce({ success: true, data: [people[4]] });
 			await renderExplorer({ initialData: partial });

